/**
 * Menubar.Submenu: a row that opens a list of its own, one level deep.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/menubar.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createMemo, createUniqueId, onMount, useContext, type JSX } from 'solid-js'
import { Portal } from 'solid-js/web'

import * as zag from '@zag-js/menu'
import { normalizeProps } from '@zag-js/solid'

import {
  Each,
  Icon,
  claimSlot,
  classes,
  createDerived,
  elementRef,
  followHighlight,
  mergeParts,
  ownerContext,
  returnFocus,
  scope,
  useDirection,
  useMachine,
  watchEffect,
} from '@polymorph/solid'
import { usePresence } from '@polymorph/solid/motion'
import styles from '@polymorph/recipes/overlays/menubar.module.css'
import Kbd from '../structure/Kbd'
import type { MenuEntry } from './Menu'
import type { MenubarOwner } from './Menubar'

export interface MenubarSubmenuProps {
  entry: MenuEntry
}

/** Menubar.Submenu: a row that opens a list of its own, one level deep. */
export default function MenubarSubmenu(given: MenubarSubmenuProps): JSX.Element {
  const props = claimSlot(given)
  const owner = useContext(ownerContext<MenubarOwner>('Menubar')) ?? ({} as MenubarOwner)
  return scope(() => {
    const uid = createUniqueId()
    const panel = elementRef<HTMLElement>()
    const row = elementRef<HTMLElement>()
    const items = createDerived(() => (props.entry.kind === 'submenu' ? props.entry.items : []))
    const documentDirection = useDirection()
    const service = useMachine(
      zag.machine,
      () =>
        ({
          id: uid,
          dir: documentDirection(),
          positioning: { placement: 'right-start', gutter: 2 },
          onSelect: (details) => {
            items.value.forEach(
              (item) => 'onSelect' in item && item.label === details.value && item.onSelect(),
            )
          },
        }) as Partial<zag.Props>,
    )
    const api = createDerived(() => zag.connect(service, normalizeProps))
    const present = usePresence(
      () => api.value.open,
      () => panel.value,
    )
    const effect1 = () => {
      void (owner.api?.setChild(service), api.value.setParent(owner.service))
    }
    onMount(effect1)
    const effect2 = () => {
      followHighlight(panel.value, api.value.highlightedValue)
    }
    watchEffect(
      createMemo(() => api.value.highlightedValue),
      effect2,
      true,
    )
    const effect3 = () => {
      void (api.value.open || returnFocus(row.value, panel.value))
    }
    watchEffect(
      createMemo(() => api.value.open),
      effect3,
      false,
    )
    return (
      <>
        {props.entry.kind === 'submenu' ? (
          <>
            {props.entry.disabled ? (
              <div
                {...mergeParts(
                  owner.api?.getItemProps({ value: props.entry.label, disabled: true }) ?? {},
                  { class: styles.item, 'data-tone': 'neutral' },
                )}
              >
                {props.entry.icon !== undefined ? (
                  <span class={styles.glyph}>
                    <Icon name={props.entry.icon} size="sm" />
                  </span>
                ) : null}
                <span class={styles.label}>{props.entry.label}</span>
                <span class={styles.hint}>
                  <Icon name="next" size="sm" />
                </span>
              </div>
            ) : (
              <div
                {...mergeParts(owner.api?.getTriggerItemProps(api.value) ?? {}, {
                  class: styles.item,
                  'data-tone': 'neutral',
                  tabindex: '-1',
                })}
                ref={row.attach}
              >
                {props.entry.icon !== undefined ? (
                  <span class={styles.glyph}>
                    <Icon name={props.entry.icon} size="sm" />
                  </span>
                ) : null}
                <span class={styles.label}>{props.entry.label}</span>
                <span class={styles.hint}>
                  <Icon name="next" size="sm" />
                </span>
              </div>
            )}
            <Portal>
              {present() ? (
                <div {...mergeParts(api.value.getPositionerProps())}>
                  <div
                    {...mergeParts(api.value.getContentProps(), {
                      class: styles.content,
                      style: {
                        '--radix-dropdown-menu-content-available-height': 'var(--available-height)',
                        '--radix-dropdown-menu-content-transform-origin': 'var(--transform-origin)',
                      },
                      hidden: undefined,
                      'oncapture:keydown': ($event: KeyboardEvent) =>
                        typeof owner.handOff === 'function' && owner.handOff($event, api.value),
                    })}
                    ref={panel.attach}
                  >
                    <Each of={items.value} by={(_entry, index) => index} renew>
                      {(entry) => (
                        <>
                          {entry.kind === 'separator' ? (
                            <div
                              {...mergeParts(api.value.getSeparatorProps(), {
                                class: styles.separator,
                              })}
                            />
                          ) : entry.kind === 'label' ? (
                            <div class={styles.groupLabel}>{entry.label}</div>
                          ) : entry.kind === 'checkbox' ? (
                            <div
                              {...mergeParts(
                                api.value.getOptionItemProps({
                                  type: 'checkbox',
                                  value: entry.label,
                                  checked: entry.checked,
                                  disabled: entry.disabled,
                                  closeOnSelect: false,
                                  onCheckedChange: entry.onCheckedChange,
                                }),
                                {
                                  class: classes(styles.item, styles.checkbox),
                                  tabindex: '-1',
                                  onfocus: () => api.value.setHighlightedValue(entry.label),
                                },
                              )}
                            >
                              <span class={styles.check}>
                                {entry.checked ? <Icon name="confirm" size="sm" /> : null}
                              </span>
                              <span class={styles.label}>{entry.label}</span>
                            </div>
                          ) : (
                            <div
                              {...mergeParts(
                                api.value.getItemProps({
                                  value: entry.label,
                                  disabled: entry.disabled,
                                }),
                                {
                                  class: styles.item,
                                  'data-tone': entry.tone ?? 'neutral',
                                  tabindex: '-1',
                                  onfocus: () => api.value.setHighlightedValue(entry.label),
                                },
                              )}
                            >
                              {entry.icon !== undefined ? (
                                <span class={styles.glyph}>
                                  <Icon name={entry.icon} size="sm" />
                                </span>
                              ) : null}
                              <span class={styles.label}>{entry.label}</span>
                              {entry.kbd !== undefined ? (
                                <span class={styles.hint}>
                                  <Kbd>{entry.kbd}</Kbd>
                                </span>
                              ) : null}
                            </div>
                          )}
                        </>
                      )}
                    </Each>
                  </div>
                </div>
              ) : null}
            </Portal>
          </>
        ) : null}
      </>
    )
  })
}
